const fs = require('fs');

const actId = '23e84a8c-5980-4787-866e-a157feef5089';
const data = [
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER I", "PRELIMINARY", "1", "Short title, Commencement, Extent.", "This Act may be called the Transfer of Property Act, 1882. It shall come into force on the first day of July, 1882. It extends to the whole of India except the territories which, immediately before the 1st November, 1956, were comprised in Part B States or in the States of Bombay, Punjab and Delhi."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER I", "PRELIMINARY", "2", "Repeal of Acts. Saving of certain enactments, incidents, rights, liabilities, etc.", "In the territories to which this Act extends for the time being the enactments specified in the Schedule hereto annexed shall be repealed to the extent therein mentioned. But nothing herein contained shall be deemed to affect— (a) the provisions of any enactment not hereby expressly repealed; (b) any terms or incidents of any contract or constitution of property which are consistent with the provisions of this Act, and are not expressly repealed thereby; (c) any right or liability arising out of a legal relation constituted before this Act comes into force, or any relief in respect of any such right or liability; or (d) save as provided by section 57 and Chapter IV of this Act, any transfer by operation of law or by or in execution of a decree or order of a Court of competent jurisdiction."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER I", "PRELIMINARY", "3", "Interpretation-clause.", "In this Act, unless there is something repugnant in the subject or context,— \"attested\", in relation to an instrument, means and shall be deemed always to have meant attested by two or more witnesses each of whom has seen the executant sign or affix his mark to the instrument and each of whom has signed the instrument in the presence of the executant; but it shall not be necessary that more than one of such witnesses shall have been present at the same time, and no particular form of attestation shall be necessary; \"actionable claim\" means a claim to any debt, other than a debt secured by mortgage of immovable property or by hypothecation or pledge of movable property, or to any beneficial interest in movable property not in the possession, either actual or constructive, of the claimant, which the civil courts recognise as affording grounds for relief, whether such debt or beneficial interest be existent, accruing, conditional or contingent; \"immovable property\" does not include standing timber, growing crops or grass; \"instrument\" means a non-testamentary instrument; \"registered\" means registered under the law for the time being in force for the registration of documents; \"attached to the earth\" means— (a) rooted in the earth, as in the case of trees and shrubs; (b) imbedded in the earth, as in the case of walls or buildings; or (c) attached to what is so imbedded for the permanent beneficial enjoyment of that to which it is attached; \"transfer of property\" means an act by which a living person conveys property, in present or in future, to one or more other living persons, or to himself and one or more other living persons; and \"to transfer property\" is to perform such act. In this section \"living person\" includes a company or association or body of individuals, whether incorporated or not, but nothing herein contained shall affect any law for the time being in force relating to transfer of property to or by companies, associations or bodies of individuals."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER I", "PRELIMINARY", "4", "Enactments relating to contracts to be taken as part of Contract Act and supplemental to the Registration Act.", "The chapters and sections of this Act which relate to contracts shall be taken as part of the Indian Contract Act, 1872. And sections 54, paragraphs 2 and 3, 59, 107 and 123 shall be read as supplemental to the Indian Registration Act, 1908."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "5", "Transfer of property defined.", "In the following sections \"transfer of property\" means an act by which a living person conveys property, in present or in future, to one or more other living persons, or to himself and one or more other living persons; and \"to transfer property\" is to perform such act. In this section \"living person\" includes a company or association or body of individuals, whether incorporated or not, but nothing herein contained shall affect any law for the time being in force relating to transfer of property to or by companies, associations or bodies of individuals."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "6", "What may be transferred.", "Property of any kind may be transferred, except as otherwise provided by this Act or by any other law for the time being in force. (a) The chance of an heir-apparent succeeding to an estate, the chance of a relation obtaining a legacy on the death of a kinsman, or any other mere possibility of a like nature, cannot be transferred. (b) A mere right of re-entry for breach of a condition subsequent cannot be transferred to any one except the owner of the property affected thereby. (c) An easement cannot be transferred apart from the dominant heritage. (d) An interest in property restricted in its enjoyment to the owner personally cannot be transferred by him. (e) A right to future maintenance, in whatsoever manner arising, secured or determined, cannot be transferred. (f) A mere right to sue cannot be transferred. (g) A public office cannot be transferred, nor can the salary of a public officer, whether before or after it has become payable. (h) No transfer can be made (1) insofar as it is opposed to the nature of the interest affected thereby, or (2) for an unlawful object or consideration within the meaning of section 23 of the Indian Contract Act, 1872, or (3) to a person legally disqualified to be transferee. (i) Nothing in this section shall be deemed to authorise a tenant having an untransferable right of occupancy, the farmer of an estate in respect of which default has been made in paying revenue, or the lessee of an estate under the management of a Court of Wards, to assign his interest as such tenant, farmer or lessee."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "7", "Persons competent to transfer.", "Every person competent to contract and entitled to transferable property, or entitled to a transferable interest in such property, is competent to transfer such property or interest either wholly or in part, and either absolutely or conditionally, in the circumstances, to the extent and in the manner, allowed and prescribed by any law for the time being in force."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "8", "Operation of transfer.", "Unless a different intention is expressed or necessarily implied, a transfer of property passes forthwith to the transferee all the interest which the transferor is then capable of passing in the property and in the legal incidents thereof. Such interest includes, where the property is land, the easements annexed thereto, the rents and profits thereof accruing after the transfer, and all things attached to the earth."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "9", "Oral transfer.", "A transfer of property may be made without writing in every case in which a writing is not expressly required by law."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "10", "Condition restraining alienation.", "Where property is transferred subject to a condition or limitation absolutely restraining the transferee or any person claiming under him from parting with or disposing of his interest in the property, the condition or limitation is void, except in the case of a lease where the condition is for the benefit of the lessor or those claiming under him: provided that property may be transferred to or for the benefit of a woman (not being a Hindu, Muhammadan or Buddhist), so that she shall not have power during her marriage to transfer or charge the same for her beneficial enjoyment."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "11", "Restriction repugnant to interest created.", "Where, on a transfer of property, an interest therein is created subject to a condition or limitation making any interest therein, reserved or given to or for the benefit of any other person, to take effect after the termination of such prior interest, and such interest is to cease on the happening of a certain event, or on the performance of a condition, such condition or limitation is void, except in the case of a lease for the life of the lessee or for any other term, where the condition is for the benefit of the lessor or those claiming under him."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "12", "Condition making interest determinable on insolvency or attempted alienation.", "Where property is transferred subject to a condition or limitation making any interest therein, reserved or given to or for the benefit of any other person, to take effect on the happening of a specified uncertain event, or on the performance of a specified uncertain condition, such condition or limitation is void, except in the case of a lease where the condition is for the benefit of the lessor or those claiming under him."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "13", "Transfer for benefit of unborn person.", "Where, on a transfer of property, an interest therein is created for the benefit of a person not in existence at the date of the transfer, subject to a prior interest created by the same transfer, the interest created for the benefit of such person shall not take effect, unless it extends to the whole of the remaining interest of the transferor in the property."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "14", "Rule against perpetuity.", "No transfer of property can operate to create an interest which is to take effect after the lifetime of one or more persons living at the date of such transfer, and the minority of some person who shall be in existence at the expiration of that period, and to whom, if he attains full age, the interest created is to belong."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "15", "Transfer to a class, some of whom come under sections 13 and 14.", "If, on a transfer of property, an interest therein is created for the benefit of a class of persons, with regard to some of whom such interest fails by reason of any of the rules contained in sections 13 and 14, such interest fails in regard to those persons only and not in regard to the whole class."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "16", "Transfer to take effect on failure of prior interest.", "Where, by reason of any of the rules contained in sections 13 and 14, an interest created on a transfer of property does not take effect, or fails, any interest created in the same transaction and intended to take effect after or upon failure of such prior interest also fails."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "17", "Direction for accumulation.", "Where the terms of a transfer of property direct that the income arising from the property shall be accumulated either wholly or in part during a period longer than the life of the transferor, or a period of eighteen years from the date of the transfer, such direction shall, save as hereinafter provided, be void to the extent to which the period during which the accumulation is directed exceeds the longer of the aforesaid periods, and at the end of such last-mentioned period the property and the income thereof shall be disposed of as if the period during which the accumulation has been directed to be made had elapsed."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "18", "Transfer in perpetuity for benefit of public.", "The restrictions in sections 14, 16 and 17 shall not apply in the case of a transfer of property for the benefit of the public which is for the advancement of religion, knowledge, commerce, health, safety or any other object beneficial to mankind."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "19", "Vested interest.", "Where, on a transfer of property, an interest therein is created in favour of a person without specifying the time when it is to take effect, or in terms specifying that it is to take effect forthwith or on the happening of an event which must happen, such interest is vested, unless a contrary intention appears from the terms of the transfer. A vested interest is not defeated by the death of the transferee before he obtains possession of the interest."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "20", "When unborn person acquires vested interest on transfer for his benefit.", "Where, on a transfer of property, an interest therein is created for the benefit of a person not then living, he acquires upon his birth, or upon the happening of the event (if any) on which the interest is made to depend, a vested interest, although he may not be entitled to the enjoyment thereof immediately on his birth."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "21", "Contingent interest.", "Where, on a transfer of property, an interest therein is created in favour of a person to take effect only on the happening of a specified uncertain event, or if a specified uncertain event shall not happen, such person thereby acquires a contingent interest in the property. Such interest becomes a vested interest, in the former case, on the happening of the event, in the latter, when the happening of the event becomes impossible. Exception.—Where, under a transfer of property, a person becomes entitled to an interest therein upon attaining a particular age, and the transferor also gives to him absolutely the income to be derived from such interest before he reaches that age, or directs the income or so much thereof as may be necessary to be applied for his benefit, such interest is not contingent."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "22", "Transfer to members of a class who attain a particular age.", "Where, on a transfer of property, an interest therein is created in favour of such members only of a class of persons as shall attain a particular age, such interest does not vest in any member of the class who has not attained that age."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "23", "Transfer contingent on happening of specified uncertain event.", "Where, on a transfer of property, an interest therein is to accrue to a specified person if a specified uncertain event shall happen, and no time is mentioned for the occurrence of that event, the interest fails unless such event happens before the period fixed for the vesting of the interest, or, if no such period is fixed, before the expiry of the period fixed by section 14 for the vesting of the interest."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "24", "Transfer to such of certain persons as survive at some period not specified.", "Where, on a transfer of property, an interest therein is to accrue to such of certain persons as shall be surviving at some period, but the exact period is not specified, the interest shall go to such of them as shall be alive when the intermediate or precedent interest ceases to exist, unless a contrary intention appears from the terms of the transfer."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "25", "Conditional transfer.", "An interest created on a transfer of property and dependent upon a condition fails if the fulfilment of the condition is impossible, or is forbidden by law, or is of such a nature that, if permitted, it would defeat the provisions of any law, or is fraudulent, or involves or implies injury to the person or property of another, or the Court regards it as immoral or opposed to public policy."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "26", "Fulfilment of condition precedent.", "Where the terms of a transfer of property impose a condition to be fulfilled before a person can take an interest in the property, the condition shall be deemed to have been fulfilled if it has been substantially complied with."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "27", "Conditional transfer to one person coupled with transfer to another on failure of prior disposition.", "Where, on a transfer of property, an interest therein is created in favour of one person, and by the same transaction an ulterior disposition of the same interest is made in favour of another, if the prior disposition under the transfer shall fail, the ulterior disposition shall take effect upon the failure of the prior disposition, although the failure may not have occurred in the manner contemplated by the transferor."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "28", "Ulterior transfer conditional on happening or not happening of specified event.", "On a transfer of property an interest therein may be created to accrue to any person with the condition superadded that in case a specified uncertain event shall happen or not happen such interest shall pass to another person. Such condition shall be deemed to be a condition subsequent."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "29", "Fulfilment of condition subsequent.", "An ulterior disposition of the kind contemplated by the last preceding section cannot take effect unless the condition is strictly fulfilled."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "30", "Prior disposition not affected by invalidity of ulterior disposition.", "If the ulterior disposition is not valid, the prior disposition is not affected by it."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "31", "Condition that transfer shall cease to have effect in case specified uncertain event happens or does not happen.", "Subject to the provisions of section 12, on a transfer of property an interest therein may be created with the condition superadded that it shall cease to exist in case a specified uncertain event shall happen, or in case a specified uncertain event shall not happen."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "32", "Such condition must not be invalid.", "In order that a condition that an interest shall cease to exist may be valid, it is necessary that the event to which it relates be one which could legally constitute the condition of a contingent interest as provided by section 25."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "33", "Transfer conditional on performance of act, no time being specified for performance.", "Where, on a transfer of property, an interest therein is created subject to a condition that the person taking it shall perform a certain act, but no time is specified for the performance of the act, the condition is broken when he renders impossible, permanently or for an indefinite period, the performance of the act."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "34", "Transfer conditional on performance of act, time being specified.", "Where an act is to be performed by a person either as a condition to be fulfilled before an interest created on a transfer of property is enjoyed by him, or as a condition on the non-fulfilment of which the interest is to pass from him to another person, and a time is specified for the performance of the act, if he fails to perform the act within the specified time, his interest in the property shall pass to the other person, or, if he does perform the act within the specified time, his interest in the property shall not pass to the other person."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "35", "Election when necessary.", "Where a person professes to transfer property which he has no right to transfer, and as part of the same transaction confers any benefit on the owner of the property, such owner must elect either to confirm such transfer or to dissent from it; and, in the latter case, he shall relinquish the benefit so conferred, and the benefit so relinquished shall revert to the transferor or his representative as if it had not been disposed of, subject nevertheless to the rights of any third person who may have, for consideration, without notice of the election of the owner of the property, derived title from the person who has elected to confirm the transfer."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "36", "Apportionment of periodical payments on determination of interest of person entitled.", "In the absence of a contract or local usage to the contrary, all rents, annuities, dividends and other periodical payments in the nature of income shall, upon the transfer of the interest of the person entitled to receive such payments, be deemed, as between the transferor and the transferee, to accrue due from day to day, and to be apportionable accordingly, but such apportionment shall not prejudice the right of the transferee to recover any instalment of such payments which may become due after the transfer."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "37", "Apportionment of benefit of obligation on severance.", "When, in consequence of a transfer, property is divided and held in several shares, and thereupon the benefit of any obligation relating to the property as a whole passes from one to several owners of the property, the corresponding duty shall, in the absence of a contract to the contrary amongst the owners, be performed in favour of each of such owners in proportion to the value of his share in the property, provided that the duty can be severed and that the severance does not substantially increase the burden of the obligation; but this provision shall not operate to enlarge the burden of any obligation on any owner."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "38", "Transfer by person authorised only under certain circumstances to transfer.", "Where any person, authorised only under circumstances in their nature variable to dispose of immovable property, transfers such property for consideration, alleging the existence of such circumstances, they shall, as between the transferee and the transferor, be deemed to have existed, if the transferee, after using reasonable care to ascertain the existence of such circumstances, has acted in good faith."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "39", "Transfer where third person is entitled to maintenance.", "Where a third person is entitled to receive maintenance, or a provision for advancement or marriage, from the profits of immovable property, and such property is transferred, the right of the third person to receive such maintenance or provision may be enforced against the transferee, if the transferee has notice of the right, or if the transfer is gratuitous; but not against a transferee for consideration and without notice of the right, nor against such property in his hands."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "40", "Transfer by unauthorised person who subsequently acquires interest in property transferred.", "Where a person fraudulently or erroneously represents that he is authorised to transfer certain immovable property and professes to transfer such property for consideration, such transfer shall, at the option of the transferee, operate on any interest which the transferor may acquire in such property at any time during which the contract of transfer subsists. Nothing in this section shall impair the right of transferees in good faith for consideration without notice of the existence of the said option."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "41", "Transfer by ostensible owner.", "Where, with the consent, express or implied, of the persons interested in immovable property, a person is the ostensible owner of such property and transfers the same for consideration, the transfer shall not be voidable on the ground that the transferor was not authorised to make it; provided that the transferee, after taking reasonable care to ascertain that the transferor had power to make the transfer, has acted in good faith."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "42", "Transfer by person having authority to revoke former transfer.", "Where a person transfers any immovable property, reserving power to revoke the transfer, and subsequently transfers the property to another for consideration, the second transfer shall, at the option of the transferee, operate to revoke the former transfer, whether made with or without consideration."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "43", "Transfer by unauthorised person who subsequently acquires interest in property transferred.", "Where a person fraudulently or erroneously represents that he is authorised to transfer certain immovable property and professes to transfer such property for consideration, such transfer shall, at the option of the transferee, operate on any interest which the transferor may acquire in such property at any time during which the contract of transfer subsists. Nothing in this section shall impair the right of transferees in good faith for consideration without notice of the existence of the said option."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "44", "Transfer by one co-owner.", "Where one of two or more co-owners of immovable property legally competent in that behalf transfers his share of such property or any interest therein, the transferee acquires, as to such share or interest, so far as is necessary to give effect to the transfer, the rights of a co-owner, and is subject to the liabilities of a co-owner."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "45", "Joint transfer for consideration.", "Where immovable property is transferred for consideration to two or more persons, and such consideration is paid out of a fund belonging to them in common, they are, in the absence of a contract to the contrary, respectively entitled to interests in such property identical, as nearly as may be, with the interests to which they were respectively entitled in the fund; and, where such consideration is paid out of separate funds belonging to them respectively, they are, in the absence of a contract to the contrary, respectively entitled to interests in such property in proportion to the shares of the consideration which they respectively advanced."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "46", "Transfer for consideration by persons having distinct interests.", "Where immovable property is transferred for consideration by persons having distinct interests therein, the respective interests of the transferors in the property shall, in the absence of a contract to the contrary, be in the proportion of the consideration paid by each."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "47", "Transfer by co-owners of share in common property.", "Where several co-owners of immovable property transfer a share therein without specifying that the transfer is to take effect on any particular share or shares of the transferors, the transfer, as among such transferors, shall be deemed to take effect on such shares equally where the shares were equal, and, where they were unequal, proportionately to the extent of such shares."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "48", "Priority of rights created by transfer.", "Where a person purports to create by transfer at different times rights in or over the same immovable property, and such rights cannot all exist or be exercised to their full extent together, each later created right shall, in the absence of a special contract or reservation binding the earlier transferees, be subject to the rights previously created."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "49", "Transferee's right under a conditional transfer.", "Where, on a transfer of property, an interest therein is created subject to a condition that the person taking it shall perform a certain act, but no time is specified for the performance of the act, the condition is broken when he renders impossible, permanently or for an indefinite period, the performance of the act."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "50", "Rent bona fide paid to holder under defective title.", "No person shall be chargeable with any rents or profits of any immovable property which he has in good faith paid or delivered to any person through whom he claims, although it may afterwards appear that the person who paid or delivered the same had no right to receive such rents or profits."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "51", "Improvements made by bona fide holders under defective titles.", "When the transferee of immovable property makes any improvement on the property, believing in good faith that he is absolutely entitled thereto, and he subsequently is evicted therefrom by any person having a better title, the transferee has a right to require the person causing the eviction either to have the value of the improvement estimated and paid or secured to the transferee, or to sell his interest in the property to the transferee at the then market value thereof, irrespective of the value of the improvement."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "52", "Transfer of property pending suit relating thereto.", "During the pendency in any Court in India of any suit or proceeding which is not collusive and in which any right to immovable property is directly and specifically in question, the property cannot be transferred or otherwise dealt with by any party to the suit or proceeding so as to affect the rights of any other party thereto under any decree or order which may be made therein, except under the authority of the Court and on such terms as it may impose. Explanation.—For the purposes of this section, the pendency of a suit or proceeding shall be deemed to commence from the date of the presentation of the plaint or the institution of the proceeding in a Court of competent jurisdiction, and to continue until the suit or proceeding has been disposed of by a final decree or order and complete satisfaction or discharge of such decree or order has been obtained, or has become unobtainable by reason of the expiration of any period of limitation prescribed for the execution thereof by any law for the time being in force."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "53", "Fraudulent transfer.", "(1) Every transfer of immovable property made with intent to defeat or delay the creditors of the transferor shall be voidable at the option of any creditor so defeated or delayed. Nothing in this sub-section shall impair the rights of a transferee in good faith and for consideration. Nothing in this sub-section shall affect any law for the time being in force relating to insolvency. (2) Every transfer of immovable property made without consideration with intent to defraud a subsequent transferee shall be voidable at the option of such transferee."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "53A", "Part performance.", "Where any person contracts to transfer for consideration any immovable property by writing signed by him or on his behalf from which the terms necessary to constitute the transfer can be ascertained with reasonable certainty, and the transferee has, in part performance of the contract, taken possession of the property or any part thereof, or the transferee, being already in possession, continues in possession in part performance of the contract and has done some act in furtherance of the contract, and the transferee has performed or is willing to perform his part of the contract, then, notwithstanding that where there is an instrument of transfer, that the transfer has not been completed in the manner prescribed therefor by the law for the time being in force, the transferor or any person claiming under him shall be debarred from enforcing against the transferee and persons claiming under him any right in respect of the property of which the transferee has taken or continued in possession, other than a right expressly provided by the terms of the contract: Provided that nothing in this section shall affect the rights of a transferee for consideration who has no notice of the contract or of the part performance thereof."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "54", "Sale defined.", "\"Sale\" is a transfer of ownership in exchange for a price paid or promised or part-paid and part-promised. Such transfer, in the case of tangible immovable property of the value of one hundred rupees and upwards, or in the case of a reversion or other intangible thing, can be made only by a registered instrument. In the case of tangible immovable property of a value less than one hundred rupees, such transfer may be made either by a registered instrument or by delivery of the property. Delivery of tangible immovable property takes place when the seller places the buyer, or such person as he directs, in possession of the property. A contract for the sale of immovable property is a contract that a sale of such property shall take place on terms settled between the parties. It does not, of itself, create any interest in or charge on such property."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "55", "Rights and liabilities of buyer and seller.", "In the absence of a contract to the contrary, the buyer and the seller of immovable property respectively are subject to the liabilities, and have the rights, mentioned in the rules next following, or such of them as are applicable to the property sold: (1) The seller is bound— (a) to disclose to the buyer any material defect in the property or in the seller's title thereto of which the seller is, and the buyer is not, aware, and which the buyer could not with ordinary care discover; (b) to produce to the buyer on his request for examination all documents of title relating to the property which are in the seller's possession or power; (c) to answer to the best of his information all relevant questions put to him by the buyer in respect of the property or the title thereto; (d) on payment or tender of the amount due in respect of the price, to execute a proper conveyance of the property when the buyer tenders it to him for execution at a proper time and place; (e) between the date of the contract of sale and the delivery of the property, to take as much care of the property and all documents of title relating thereto which are in his possession as an owner of ordinary prudence would take of such property and documents; (f) to give, on being so required, the buyer or such person as he directs, such possession of the property as its nature admits; (g) to pay all public charges and rent accrued due in respect of the property up to the date of the sale, the interest on all encumbrances on such property due on such date, and, except where the property is sold subject to encumbrances, to discharge all encumbrances on the property then existing. (2) The seller shall be deemed to contract with the buyer that the interest which the seller professes to transfer to the buyer subsists and that he has power to transfer the same: Provided that, where the sale is made by a person in a fiduciary character, he shall be deemed to contract with the buyer that the seller has done no act whereby the property is encumbered or whereby he is hindered from transferring it. The benefit of the contract mentioned in this clause shall be annexed to, and shall go with, the interest of the transferee as such, and may be enforced by every person in whom that interest is for the whole or any part thereof from time to time vested. (3) Where the ownership of the property has passed to the buyer, he is entitled to the benefit of any improvement in, or increase in value of, the property, and to the rents and profits thereof. The buyer is bound— (a) to disclose to the seller any fact as to the nature or extent of the seller's interest in the property of which the buyer is aware, but of which he has reason to believe that the seller is not aware, and which materially increases the value of such interest; (b) to pay or tender, at the time and place of completing the sale, the purchase-money to the seller or such person as he directs: provided that, where the property is sold free from encumbrances, the buyer may retain out of the purchase-money the amount of any encumbrances on the property existing at the date of the sale, and shall pay the amount so retained to the persons entitled thereto; (c) where the ownership of the property has passed to the buyer, to bear the loss arising from the destruction, injury or decrease in value of the property not caused by the seller; (d) where the property is not in a deliverable state, or where the seller is bound to do something to the property for the purpose of putting it into a deliverable state, to bear any loss arising from the destruction, injury or decrease in value of the property, not caused by the seller, after the property has been put into a deliverable state and the buyer has notice thereof; (e) to pay all public charges and rent which may become payable in respect of the property, the principal moneys due on any encumbrances subject to which the property is sold, and the interest thereon afterwards accruing due."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "56", "Marshalling by subsequent purchaser.", "If the owner of two or more properties mortgages them to one person and then sells one or more of the properties to another person, the buyer is, in the absence of a contract to the contrary, entitled to have the mortgage-debt satisfied out of the property or properties not sold to him, so far as the same will extend, but not so as to prejudice the rights of the mortgagee or persons claiming under him or any other person who has for consideration acquired an interest in any of the properties."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER II", "OF TRANSFERS OF PROPERTY BY ACT OF PARTIES", "57", "Provision by Court for incumbrances and sale freed therefrom.", "Where immovable property subject to any incumbrance is sold by the Court, or in execution of a decree, or out of Court, the Court may, if it thinks fit, on the application of any party to the sale, direct or allow payment into Court,— (1) in the case of an annual or monthly sum charged on the property, or of a capital sum charged on a determinable interest in the property—of such amount as, when invested in securities of the Central Government, the Court considers will be sufficient, by means of the interest thereof, to keep down or otherwise provide for that charge, and (2) in any other case of a capital sum charged on the property—of the amount sufficient to meet the incumbrance and any interest due thereon. But in either case there shall also be paid into Court such additional amount as the Court considers will be sufficient to meet the contingency of further costs, expenses and interest, and any other contingency, except depreciation of investments, not exceeding one-tenth part of the original amount to be paid in, unless the Court for special reasons (which it shall record) thinks fit to require a large additional amount. Thereupon the Court may, if it thinks fit, and shall, on the request of the mortgagee or other person entitled to the charge, direct that the property shall be sold free from the incumbrance, and the proceeds of sale shall be applied in or towards— (i) payment of the incumbrance, and (ii) payment of any amount directed by the Court to be paid into Court under the foregoing provisions, and (iii) payment of any amount which the Court may direct to be paid to the mortgagee or other person entitled to the charge for costs and expenses properly incurred by him in respect of the incumbrance. The residue, if any, shall be applied in payment of any costs and expenses properly incurred by the person who applied for the sale or by any subsequent incumbrancer, and the balance, if any, shall be paid to the person entitled to receive the same."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER III", "OF SALES OF IMMOVABLE PROPERTY", "54", "Sale defined. (Repeated from earlier for completeness in chapter context)", "\"Sale\" is a transfer of ownership in exchange for a price paid or promised or part-paid and part-promised..."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER III", "OF SALES OF IMMOVABLE PROPERTY", "55", "Rights and liabilities of buyer and seller. (Repeated from earlier for completeness)", "In the absence of a contract to the contrary, the buyer and the seller of immovable property respectively are subject to the liabilities, and have the rights, mentioned in the rules next following..."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "58", "“Mortgage”, “mortgagor”, “mortgagee”, “mortgage-money” and “mortgage-deed” defined.", "(a) A mortgage is the transfer of an interest in specific immovable property for the purpose of securing the payment of money advanced or to be advanced by way of loan, an existing or future debt, or the performance of an engagement which may give rise to a pecuniary liability. The transferor is called a mortgagor, the transferee a mortgagee; the principal money and interest of which payment is secured for the time being are called the mortgage-money, and the instrument (if any) by which the transfer is effected is called a mortgage-deed. (b) Simple mortgage.—Where, without delivering possession of the mortgaged property, the mortgagor binds himself personally to pay the mortgage-money, and agrees, expressly or impliedly, that, in the event of his failing to pay according to his contract, the mortgagee shall have a right to cause the mortgaged property to be sold and the proceeds of sale to be applied, so far as may be necessary, in payment of the mortgage-money, the transaction is called a simple mortgage and the mortgagee a simple mortgagee. (c) Mortgage by conditional sale.—Where the mortgagor ostensibly sells the mortgaged property— on condition that on default of payment of the mortgage-money on a certain date the sale shall become absolute, or on condition that on such payment being made the sale shall become void, or on condition that on such payment being made the buyer shall transfer the property to the seller, the transaction is called a mortgage by conditional sale and the mortgagee a mortgagee by conditional sale: Provided that no such transaction shall be deemed to be a mortgage, unless the condition is embodied in the document which effects or purports to effect the sale. (d) Usufructuary mortgage.—Where the mortgagor delivers possession or expressly or by implication binds himself to deliver possession of the mortgaged property to the mortgagee, and authorises him to retain such possession until payment of the mortgage-money, and to receive the rents and profits accruing from the property or any part of such rents and profits and to appropriate the same in lieu of interest, or in payment of the mortgage-money, or partly in lieu of interest or partly in payment of the mortgage-money, the transaction is called an usufructuary mortgage and the mortgagee an usufructuary mortgagee. (e) English mortgage.—Where the mortgagor binds himself to repay the mortgage-money on a certain date, and transfers the mortgaged property absolutely to the mortgagee, but subject to a proviso that he will re-transfer it to the mortgagor upon payment of the mortgage-money as agreed, the transaction is called an English mortgage. (f) Mortgage by deposit of title-deeds.—Where a person in any of the following towns, namely, the towns of Calcutta, Madras and Bombay, and in any other town which the State Government concerned may, by notification in the Official Gazette, specify in this behalf, delivers to a creditor or his agent documents of title to immovable property, with intent to create a security thereon, the transaction is called a mortgage by deposit of title-deeds. (g) Anomalous mortgage.—A mortgage which is not a simple mortgage, a mortgage by conditional sale, an usufructuary mortgage, an English mortgage or a mortgage by deposit of title-deeds within the meaning of this section is called an anomalous mortgage."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "59", "Mortgage when to be by assurance.", "Where the principal money secured is one hundred rupees or upwards, a mortgage other than a mortgage by deposit of title-deeds can be effected only by a registered instrument signed by the mortgagor and attested by at least two witnesses. Where the principal money secured is less than one hundred rupees, a mortgage may be effected either by a registered instrument signed and attested as aforesaid or (except in the case of a simple mortgage) by delivery of the property."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "59A", "References to mortgagors and mortgagees to include persons deriving title from them.", "Unless otherwise expressly provided, references in this Chapter to mortgagors and mortgagees shall be deemed to include references to persons deriving title from them respectively."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "60", "Right of mortgagor to redeem.", "At any time after the principal money has become due, the mortgagor has a right, on payment or tender, at a proper time and place, of the mortgage-money, to require the mortgagee— (a) to deliver to the mortgagor the mortgage-deed and all documents relating to the mortgaged property which are in the possession or power of the mortgagee, (b) where the mortgagee is in possession of the mortgaged property, to deliver possession thereof to the mortgagor, and (c) at the cost of the mortgagor either to re-transfer the mortgaged property to him or to such third person as he directs, or to execute and (where the mortgage has been effected by a registered instrument) to have registered an acknowledgement in writing that any right in derogation of the mortgagor's interest transferred to the mortgagee has been extinguished: Provided that the right conferred by this section has not been extinguished by act of the parties or by decree of a Court. The right conferred by this section is called a right to redeem and a suit to enforce it is called a suit for redemption. Nothing in this section shall be deemed to render invalid any provision to the effect that, if the time fixed for payment of the mortgage-money or any part thereof is allowed to pass or in the case of a usufructuary mortgage, if no such time is fixed, then, if the mortgagor fails to pay, or tender in pursuance of a notice in writing served on him by the mortgagee or by his agent in that behalf, the mortgage-money or any part thereof, within three months from the date of the service of such notice, the mortgagee shall be at liberty to sell the mortgaged property by public auction and appropriate the proceeds towards the mortgage-money."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "60A", "Obligation to transfer to third party instead of re-transference to mortgagor.", "(1) Where a mortgagor is entitled to redemption, then, on the fulfilment of any conditions of the mortgage, he may require the mortgagee, instead of re-transferring the property, to assign the mortgage-deed and transfer the mortgaged property to such third person as the mortgagor directs; and the mortgagee shall be bound to assign and transfer accordingly. (2) The rights conferred by this section belong to and may be enforced by the mortgagor or by any encumbrancer notwithstanding an intermediate encumbrance; but the requisition of any encumbrance shall prevail over that of the mortgagor."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "60B", "Right to inspection and production of documents.", "A mortgagor, as long as his right of redemption subsists, shall be entitled at all reasonable times, at his request and at his own cost, and on payment of the mortgagee's costs and expenses in this behalf, to inspect and make copies or abstracts of, or extracts from, documents of title relating to the mortgaged property which are in the custody or power of the mortgagee."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "61", "Right to redeem separately or simultaneously.", "A mortgagor who has executed two or more mortgages in favour of the same mortgagee shall, in the absence of a contract to the contrary, be entitled to redeem any one such mortgage separately, or any two or more of such mortgages together."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "62", "Right of usufructuary mortgagor to recover possession.", "In the case of a usufructuary mortgage, the mortgagor has a right to recover possession of the property together with the mortgage-deed and all documents relating to the mortgaged property which are in the possession or power of the mortgagee— (a) where the mortgagee is authorised to pay himself the mortgage-money from the rents and profits of the property,—when such money is paid; (b) where the mortgagee is authorised to pay himself from such rents and profits or any part thereof a part only of the mortgage-money,—when the term (if any) prescribed for the payment of the mortgage-money has expired and the mortgagor pays or tenders to the mortgagee the mortgage-money or the balance thereof or deposits it in Court as hereinafter provided."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "63", "Accession to mortgaged property.", "Where mortgaged property in possession of the mortgagee has, during the continuance of the mortgage, received any accession, the mortgagor, upon redemption, shall, in the absence of a contract to the contrary, be entitled as against the mortgagee to such accession. Accession acquired in virtue of transferred ownership.—Where such accession has been acquired at the expense of the mortgagee, the mortgagor shall, in the absence of a contract to the contrary, be entitled to the accession as aforesaid upon payment of the cost thereof to the mortgagee."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "63A", "Improvements to mortgaged property.", "(1) Where mortgaged property in possession of the mortgagee has, during the continuance of the mortgage, received any accession or been improved by the mortgagee at his own cost, the mortgagor, upon redemption, shall, in the absence of a contract to the contrary, be entitled to the accession or improvement, as the case may be, upon payment of the cost thereof to the mortgagee. (2) Where any such improvement has been effected at the cost of the mortgagee and was necessary to preserve the property from destruction or to prevent the security from becoming insufficient, the mortgagee shall be entitled to the cost thereof from the mortgagor. (3) Where any such improvement was effected at the cost of the mortgagee, but was not necessary to preserve the property from destruction or to prevent the security from becoming insufficient, the mortgagor shall be entitled to the improvement upon payment of the cost thereof to the mortgagee."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "64", "Right of mortgagee to foreclose or sell.", "In the absence of a contract to the contrary, the mortgagee has, at any time after the mortgage-money has become due to him, and before a decree has been made for the redemption of the mortgaged property, or the mortgage-money has been paid or deposited as hereinafter provided, a right to obtain from the Court a decree that the mortgagor shall be absolutely debarred of his right to redeem the property, or a decree that the property be sold. A suit to obtain a decree that a mortgagor shall be absolutely debarred of his right to redeem the mortgaged property is called a suit for foreclosure. Nothing in this section shall be deemed— (a) to authorise any mortgagee other than a mortgagee by conditional sale or a mortgagee under an anomalous mortgage by the terms of which he is entitled to foreclose, to institute a suit for foreclosure, or an usufructuary mortgagee as such or a mortgagee by conditional sale as such to institute a suit for sale; or (b) to authorise a mortgagor who holds the mortgagee's rights as his trustee or legal representative, and who may sue for a sale of the property, to institute a suit for foreclosure; or (c) to authorise the mortgagee of a railway, canal or other work in the maintenance of which the public are interested, to institute a suit for foreclosure or sale; or (d) to authorise a person interested in part only of the mortgage-money to institute a suit relating only to a corresponding part of the mortgaged property, unless the mortgagees have, with the consent of the mortgagor, severed their interests under the mortgage."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "65", "Rights of mortgagor in possession.", "In the absence of a contract to the contrary, the mortgagor, as long as he is in possession of the mortgaged property, shall be entitled to the rents and profits thereof."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "65A", "Mortgagor's power to lease.", "(1) Subject to the provisions of sub-section (2), a mortgagor, while lawfully in possession of the mortgaged property, shall have power to make leases thereof which shall be binding on the mortgagee. (2) (a) Every such lease shall be such as would be binding on the mortgagor if he were in possession of the property, and shall be for a period not exceeding three years or, if the mortgage-money is repayable by instalments, for a period not exceeding the time fixed for the payment of any instalment; (b) no such lease shall contain a covenant for renewal; (c) every such lease shall take effect from a date not later than six months from the date on which it is made; (d) no such lease shall reserve a rent which is more than the rent reserved by the last preceding lease or, if there was no such lease, which is more than the rent for which the property was let immediately before the mortgage; and (e) every such lease shall reserve the best rent that can reasonably be obtained."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "66", "Waste by mortgagor in possession.", "A mortgagor in possession of the mortgaged property is not liable to the mortgagee for allowing the property to deteriorate; but he must not commit any act which is destructive or permanently injurious thereto, if the security is insufficient or will be rendered insufficient by such act. Explanation.—A security is insufficient within the meaning of this section unless the value of the mortgaged property exceeds by one-third, or, if consisting of buildings, exceeds by one-half, the amount for the time being due on the mortgage."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "67", "Right to foreclosure or sale.", "In the absence of a contract to the contrary, the mortgagee has at any time after the mortgage-money has become due to him, and before a decree has been made for the redemption of the mortgaged property, or the mortgage-money has been paid or deposited as hereinafter provided, a right to obtain from the Court a decree that the mortgagor shall be absolutely debarred of his right to redeem the property, or a decree that the property be sold."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "67A", "Mortgagee when bound to bring one suit on several mortgages.", "A mortgagee who holds two or more mortgages executed by the same mortgagor in respect of each of which he has a right to obtain the same kind of decree under section 67, and who sues to obtain such decree on any one of the mortgages, shall, in the absence of a contract to the contrary, be bound to sue on all the mortgages in respect of which the mortgage-money has become due."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "68", "Right to sue for mortgage-money.", "(1) The mortgagee has a right to sue for the mortgage-money in the following cases and no others, namely:— (a) where the mortgagor binds himself to repay the same; (b) where, by any cause other than the wrongful act or default of the mortgagor or mortgagee, the mortgaged property is wholly or partially destroyed or the security is rendered insufficient within the meaning of section 66, and the mortgagee has given the mortgagor a reasonable opportunity of providing further security enough to render the whole security sufficient, and the mortgagor has failed to do so; (c) where the mortgagee is deprived of the whole or part of his security by or in consequence of the wrongful act or default of the mortgagor; (d) where, the mortgagee being entitled to possession of the mortgaged property, the mortgagor fails to deliver the same to him, or to secure the possession thereof to him without disturbance by the mortgagor or any person claiming under a title superior to that of the mortgagor: Provided that, in the case referred to in clause (a), a transferee from the mortgagor or from his legal representative shall not be liable to be sued for the mortgage-money unless the transferee has, by an express or implied contract with the mortgagor or his legal representative, undertaken to pay the mortgage-money. (2) Where a suit is brought under clause (a) or clause (b) of sub-section (1), the Court may, at its discretion, stay the suit and all proceedings therein, notwithstanding any contract to the contrary, until the mortgagee has exhausted his remedy against the mortgaged property or what remains of it."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "69", "Power of sale when valid.", "(1) A mortgagee who holds a power of sale without the intervention of the Court may, at any time after the mortgage-money has become due and has not been paid, or the mortgagor has failed to perform any covenant or condition of the mortgage, sell the mortgaged property or any part thereof by public auction or by private contract in one or more lots, and either for a lump sum or for instalments, and may, subject to the provisions of this section, convey or assign the property sold to the purchaser free from all incumbrances created by the mortgagor. (2) The power of sale shall not be exercised unless and until— (a) notice in writing requiring payment of the mortgage-money has been served on the mortgagor, or on one of several mortgagors, and default has been made in payment of the mortgage-money, or of part thereof, for three months after such service; or (b) some interest under the mortgage amounting at least to five hundred rupees is in arrear and unpaid for three months after becoming due. (3) When a power of sale has been conferred by the mortgage on the mortgagee, the mortgagee may, at any time after the mortgage-money has become due, appoint a receiver of the income of the mortgaged property or any part thereof; and such receiver shall be deemed to be the agent of the mortgagor, and the mortgagor shall be solely responsible for the receiver's acts or defaults unless the mortgage-deed otherwise provides or unless such acts or defaults are due to the improper or insufficient instructions of the mortgagee. (4) The receiver shall have power to demand and recover all the income of which he is appointed receiver, by suit, execution or otherwise, in the name either of the mortgagor or of the mortgagee to the full extent of the interest which the mortgagor could dispose of, and to give valid receipts accordingly for the same, and to exercise the powers of the mortgagor in regard to the management and protection of the property. (5) The receiver shall apply the income received by him as follows:— firstly, in discharge of all rents and outgoings whatever affecting the mortgaged property; secondly, in payment of the interest falling due under the mortgage; thirdly, in payment of the principal money due on the mortgage if so directed in writing by the mortgagee; and fourthly, the residue, if any, shall be paid to the mortgagor. (6) The receiver shall be entitled to retain out of any money received by him, for his remuneration, and in satisfaction of all costs, charges and expenses incurred by him as receiver, a commission at such rate not exceeding five per cent. on the gross amount of all money received as is specified in his appointment, and if no rate is so specified, then at the rate of five per cent. on that gross amount, or at such other rate as the Court thinks fit to allow, on application made by him for that purpose. (7) The receiver shall, if so directed in writing by the mortgagee, insure and keep insured against loss or damage by fire the whole or any part of the property which is of an insurable nature, and the premiums paid for any such insurance shall be a charge on the mortgaged property in addition to the mortgage-money and with the same priority and with interest at the same rate as the mortgage-money. (8) The receiver may, if so directed in writing by the mortgagee, bring or defend any suit or other proceeding in the name of the mortgagor or of the mortgagee in relation to the mortgaged property, and shall, when so directed, indemnify the mortgagee against all costs, charges and expenses incurred by the mortgagee in respect of any such suit or proceeding. (9) The receiver shall, subject to the provisions of this section and to the directions of the mortgagee, use his best endeavours to collect all rents and other income of the mortgaged property, and to manage and protect the property as a prudent owner would manage and protect the same. (10) The receiver may, if so directed in writing by the mortgagee, effect any repairs or make any improvements on the mortgaged property which the mortgagee might have effected or made. (11) The receiver shall pay over to the mortgagee the money which he has received, after deducting his commission and the expenses of management, and shall keep clear, full and accurate accounts of all receipts and payments, and shall, at all reasonable times, produce the same for inspection of the mortgagor or the mortgagee. (12) The receiver shall be entitled to remuneration at such rate as the mortgagee may fix, and the amount of such remuneration shall be a charge on the mortgaged property in addition to the mortgage-money and with the same priority and with interest at the same rate as the mortgage-money. (13) The receiver may, if so directed in writing by the mortgagee, insure the whole or any part of the property which is of an insurable nature against loss or damage by fire, and the premiums paid for any such insurance shall be a charge on the mortgaged property in addition to the mortgage-money and with the same priority and with interest at the same rate as the mortgage-money. (14) The receiver may, if so directed in writing by the mortgagee, bring or defend any suit or other proceeding in the name either of the mortgagor or of the mortgagee in relation to the mortgaged property, and shall, when so directed, indemnify the mortgagee against all costs, charges and expenses incurred by the mortgagee in respect of any such suit or proceeding. (15) The receiver shall pay over to the mortgagee the money which he has received, after deducting his commission and the expenses of management, and shall keep clear, full and accurate accounts of all receipts and payments, and shall, at all reasonable times, produce the same for inspection of the mortgagor or the mortgagee."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "69A", "Appointment of receiver.", "A mortgagee entitled to appoint a receiver under the power conferred by section 69 may, by a writing signed by him or on his behalf, appoint such person as he thinks fit to be receiver of the income of the mortgaged property or any part thereof. Any person so appointed shall be deemed to be the agent of the mortgagor, and the mortgagor shall be solely responsible for the receiver's acts or defaults unless the mortgage-deed otherwise provides or unless such acts or defaults are due to the improper or insufficient instructions of the mortgagee."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "70", "Accession to mortgaged property.", "If, after the date of a mortgage, any accession is made to the mortgaged property, the mortgagee, in the absence of a contract to the contrary, shall, for the purposes of the security, be entitled to such accession."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "71", "Rights of mesne mortgagee.", "Where property is mortgaged to two or more persons in succession, the mesne mortgagee has the same rights against the prior mortgagee as he has against the mortgagor."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "72", "Right of mortgagee in possession to expenses and repairs.", "A mortgagee in possession has a right to spend such money as is necessary— (a) for the preservation of the mortgaged property from destruction, forfeiture or sale; (b) for supporting the mortgagor's title to the property; (c) for making his own title thereto good against the mortgagor; and (d) when the mortgaged property is a building, for the renewal of any parts thereof which may be worn out or destroyed by natural causes. And the mortgagee may add such money to the principal money, at the rate of interest payable on the principal, and, where no such rate is fixed, at the rate of nine per cent. per annum: Provided that the expenditure of money by the mortgagee under clause (b) or clause (c) shall not be deemed necessary unless the mortgagor has been called upon and has failed to take proper and timely steps to preserve the property or to support the title."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "73", "Right to proceeds of revenue sale or compensation on acquisition.", "Where the mortgaged property or any part thereof is sold for the recovery of arrears of revenue or other public charges, or is compulsorily acquired under any law for the time being in force, the mortgagee has a right to claim payment of the mortgage-money, in whole or in part, out of any surplus of the sale-proceeds remaining after payment of the arrears, or out of any compensation awarded for the acquisition."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "74", "Right of subsequent mortgagee to pay off prior mortgagee.", "Any subsequent mortgagee may at any time after the amount under the prior mortgage has become due, pay off the prior mortgagee and redeem the property."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "75", "Rights of mesne mortgagee against prior and subsequent mortgagees.", "A mesne mortgagee has the same rights against the prior mortgagee as he has against the mortgagor, and the same rights against the subsequent mortgagee as he has against the mortgagor."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "76", "Liabilities of mortgagee in possession.", "When, during the continuance of the mortgage, the mortgagee takes possession of the mortgaged property,— (a) he must manage the property as a person of ordinary prudence would manage it if it were his own; (b) he must use his best endeavours to collect the rents and profits thereof; (c) he must, in the absence of a contract to the contrary, out of the income of the property, pay the Government revenue, all other charges of a public nature and all rent accruing due in respect thereof during such possession, and any arrears of rent in default of payment of which the property may be summarily sold; (d) he must in the absence of a contract to the contrary, make such necessary repairs of the property as he can pay for out of the income thereof, after deducting from such income the payments mentioned in clause (c) and the interest on the principal money; (e) he must not commit any act which is destructive or permanently injurious to the property; (f) where he has insured the whole or any part of the property against loss or damage by fire, he must, on the renewal of the insurance policy, pay the premium in respect thereof; (g) he must keep clear, full and accurate accounts of all sums received and spent by him as mortgagee, and, at any time during the continuance of the mortgage, give the mortgagor, at his request and cost, true copies of such accounts and of the vouchers by which they are supported; (h) his receipts from the mortgaged property, or, where such property is personally occupied by him, a fair occupation-rent in respect thereof, shall, after deducting the expenses properly incurred for the management of the property and the collection of rents and profits and the other payments mentioned in clause (c), and interest thereon, be applied in reduction of the amount (if any) from time to time due to him on account of interest and, thereafter, of the principal money; (i) when the mortgagor tenders, or deposits in manner hereinafter provided, the amount for the time being due on the mortgage, the mortgagee must, notwithstanding the provisions in the other clauses of this section, account for his gross receipts from the mortgaged property; and (j) when the mortgagee, while in possession of the mortgaged property, has made any improvements thereon which have increased its value, he is entitled, on redemption, to the value of such improvements at the time of redemption."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "77", "Receipts in lieu of interest.", "Nothing in section 76, clauses (b), (d), (g) and (h), applies to cases where there is a contract between the mortgagee and the mortgagor that the receipts from the mortgaged property shall, so long as the mortgagee is in possession of the property, be taken in lieu of interest on the principal money, or in lieu of such interest and defined portions of the principal."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "78", "Postponement of prior mortgagee.", "Where, through the fraud, misrepresentation or gross neglect of prior mortgagee, another person has been induced to advance money on the security of the mortgaged property, the prior mortgagee shall be postponed to the subsequent mortgagee."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "79", "Mortgage to secure uncertain amount when maximum is expressed.", "If a mortgage made to secure future advances, the performance of an engagement or the balance of a running account, expresses the maximum to be secured thereby, a subsequent mortgage of the same property shall, if made with notice of the prior mortgage, be postponed to the prior mortgage in respect of all advances or debits not exceeding the maximum, though made or allowed after the execution of the subsequent mortgage; and no mortgage made in pursuance of a binding contract to advance the whole of a sum of money secured by the mortgage shall, to the extent of such sum of money, be postponed to a subsequent mortgage of the same property, though made with notice of the prior mortgage, except in cases where the prior mortgagee is bound to make the subsequent advances."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "80", "Tacking of further advances.", "[Repealed by the Transfer of Property (Amendment) Act, 1929 (20 of 1929), Section 41.]"],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "81", "Marshalling securities.", "If the owner of two or more properties mortgages them to one person and then mortgages one or more of the properties to another person, the subsequent mortgagee is, in the absence of a contract to the contrary, entitled to have the prior mortgage-debt satisfied out of the property or properties not mortgaged to him, so far as such property or properties will extend, but not so as to prejudice the rights of the prior mortgagee or of any other person who has for consideration acquired an interest in any of the properties."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "82", "Contribution to mortgage-debt.", "Where property subject to a mortgage belongs to two or more persons having distinct and separate rights of ownership therein, the different shares in or parts of such property owned by such persons are, in the absence of a contract to the contrary, liable to contribute rateably to the debt secured by the mortgage, and, for the purpose of determining the rate at which each such share or part shall contribute, the value thereof shall be deemed to be its value at the date of the mortgage after deduction of the amount of any other mortgage or charge to which it may have been subject on that date."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "83", "Power to deposit in Court money due on mortgage.", "At any time after the principal money payable in respect of any mortgage has become due and before a suit for redemption of the mortgaged property is barred, the mortgagor, or any other person entitled to institute such suit, may deposit, in any Court in which a suit might be brought to redeem the mortgage, the amount remaining due on the mortgage. The Court shall thereupon cause written notice of the deposit to be served on the mortgagee, and the mortgagee may, on presenting a petition (verified in manner prescribed by law for the verification of plaints) stating the amount then due on the mortgage, and his willingness to accept the money so deposited in full discharge of such amount, and on depositing in the same Court the mortgage-deed and all documents relating to the mortgaged property which are in his possession or power, apply for and receive the money, and the mortgage-deed, and all such other documents so deposited shall be delivered to the mortgagor or such other person as aforesaid. Where the mortgagee is in possession of the mortgaged property, the Court shall, before paying to him the amount so deposited, direct him to deliver possession thereof to the mortgagor or such other person as aforesaid, and he shall be entitled to a decree for the amount so deposited and for the costs of the suit, if any, which shall be payable by the mortgagor or such other person as aforesaid."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "84", "Cessation of interest.", "When the mortgagor or such other person as aforesaid has deposited in Court under section 83 the amount remaining due on the mortgage, interest on the mortgage-money shall cease from the date of the service of the notice on the mortgagee."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "85", "Parties to suits for foreclosure, sale and redemption.", "[Repealed by the Code of Civil Procedure, 1908 (5 of 1908), Section 156 and Schedule V.]"],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER IV", "OF MORTGAGES OF IMMOVABLE PROPERTY AND CHARGES", "86 to 90", "[Repealed by the Code of Civil Procedure, 1908 (5 of 1908), Section 156 and Schedule V.]"],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER V", "OF LEASES OF IMMOVABLE PROPERTY", "105", "Lease defined.", "A lease of immovable property is a transfer of a right to enjoy such property, made for a certain time, express or implied, or in perpetuity, in consideration of a price paid or promised, or of money, a share of crops, service or any other thing of value, to be rendered periodically or on specified occasions to the transferor by the transferee, who accepts the transfer on such terms. The transferor is called the lessor, the transferee is called the lessee, the price is called the premium, and the money, share, service or other thing to be so rendered is called the rent."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER V", "OF LEASES OF IMMOVABLE PROPERTY", "106", "Duration of certain leases in absence of written contract or local usage.", "In the absence of a written contract or local usage to the contrary, a lease of immovable property for agricultural or manufacturing purposes shall be deemed to be a lease from year to year, terminable, on the part of either lessor or lessee, by six months' notice expiring with the end of a year of the tenancy; and a lease of immovable property for any other purpose shall be deemed to be a lease from month to month, terminable, on the part of either lessor or lessee, by fifteen days' notice expiring with the end of a month of the tenancy. Every notice under this section must be in writing, signed by or on behalf of the person giving it, and either be sent by post to the party who is intended to be bound by it or be tendered or delivered personally to such party, or to one of his family or servants at his residence, or (if such_tender or delivery is not practicable) affixed to a conspicuous part of the property."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER V", "OF LEASES OF IMMOVABLE PROPERTY", "107", "Leases how made.", "A lease of immovable property from year to year, or for any term exceeding one year, or reserving a yearly rent, can be made only by a registered instrument. All other leases of immovable property may be made either by a registered instrument or by oral agreement accompanied by delivery of possession. Where a lease of immovable property is made by a registered instrument, such instrument or, where there are more instruments than one, each such instrument shall be executed by both the lessor and the lessee: Provided that the State Government may from time to time, by notification in the Official Gazette, direct that leases of immovable property, other than leases from year to year, or for any term exceeding one year, or reserving a yearly rent, or any class of such leases, may be made by unregistered instrument or by oral agreement without delivery of possession."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER V", "OF LEASES OF IMMOVABLE PROPERTY", "108", "Rights and liabilities of lessor and lessee.", "In the absence of a contract or local usage to the contrary, the lessor and the lessee of immovable property, as against one another, respectively, possess the rights and are subject to the liabilities mentioned in the rules next following, or such of them as are applicable to the property leased:— (A) Rights and Liabilities of the Lessor (a) The lessor is bound to disclose to the lessee any material defect in the property, with reference to its intended use, of which the former is and the latter is not aware, and which the latter could not with ordinary care discover; (b) the lessor is bound on the lessee's request to put him in possession of the property; (c) the lessor shall be deemed to contract with the lessee that, if the latter pays the rent reserved by the lease and performs the contracts binding on the lessee, he may hold the property during the time limited by the lease without interruption. The benefit of such contract shall be annexed to and go with the lessee's interest as such, and may be enforced by every person in whom that interest is for the whole or any part thereof from time to time vested. (B) Rights and Liabilities of the Lessee (a) If during the continuance of the lease any accession is made to the property, such accession (subject to the law relating to alluvion for the time being in force) shall be deemed to be comprised in the lease; (b) if by fire, tempest or flood, or violence of an army or of a mob, or other irresistible force, any material part of the property be wholly destroyed or rendered substantially and permanently unfit for the purposes for which it was let, the lease shall, at the option of the lessee, be void: Provided that, if the injury be occasioned by the wrongful act or default of the lessee, he shall not be entitled to avail himself of the benefit of this provision; (c) if the lessor neglects to make, within a reasonable time after notice, any repairs which he is bound to make to the property, the lessee may make the same himself, and deduct the expense of such repairs with interest from the rent, or otherwise recover it from the lessor; (d) if the lessor neglects to make any payment which he is bound to make, and which, if not made by him, is recoverable from the lessee or against the property, the lessee may make such payment himself, and deduct it with interest from the rent, or otherwise recover it from the lessor; (e) the lessee may even after the determination of the lease remove, at any time whilst he is in possession of the property leased but not afterwards all things which he has attached to the earth; provided he leaves the property in the state in which he received it; (f) the lessee may use the property and its products (if any) according to the purpose for which they were let, and, if there is no such purpose, according to the custom of the locality in which the property is situate, and, if there is no such custom, according to the nature of the property; (g) the lessee may transfer absolutely or by way of mortgage or sub-lease the whole or any part of his interest in the property, and any transferee of such interest or part may again transfer it or any part thereof, but the lessee shall not, by reason only of such transfer, cease to be subject to any of the liabilities attaching to the lease; nothing in this clause shall be deemed to authorise a tenant having an untransferable right of occupancy, the farmer of an estate in respect of which default has been made in paying revenue, or the lessee of an estate, under the management of a Court of Wards, to assign his interest as such tenant, farmer or lessee; (h) the lessee may make any additions to or improvements in the property leased, but he shall not be entitled to any compensation for such additions or improvements unless they were made with the lessor's consent; (i) the lessee may, if the lessor neglects to make within a reasonable time after notice any repairs which he is bound to make, make the same himself and deduct the expense thereof with interest from the rent or otherwise recover the same from the lessor; (j) the lessee may, even after the determination of the lease, remove, at any time during the continuance of his possession, all things which he has attached to the earth; provided he leaves the property in the state in which he received it; (k) the lessee is bound to disclose to the lessor any fact as to the nature or extent of the interest in the property of which the lessee is aware but of which he has reason to believe that the lessor is not aware, and which materially increases the value of such interest; (l) the lessee is bound to pay or tender, at the proper time and place, the premium or rent to the lessor or his agent in this behalf; (m) the lessee is bound to keep, and on the termination of the lease to restore, the property in as good condition as it was at the time when he was put in possession, subject only to the changes caused by reasonable wear and tear or irresistible force, and to allow the lessor and his agents, at all reasonable times during the continuance of the lease, to enter upon the property and inspect the condition thereof and give or leave notice of any defect in such condition; and, when such defect has been caused by any act or default on the part of the lessee, he is bound to make it good within three months after such notice has been given or left; (n) if the lessee becomes aware of any proceeding to recover the property or any part thereof, or of any encroachment made upon, or any interference with, the lessor's rights in respect of the property, he is bound to give, with reasonable diligence, notice thereof to the lessor; (o) the lessee may use the property and its products (if any) according to the purpose for which they were let, and if there is no such purpose, according to the custom of the locality in which the property is situate, and if there is no such custom, according to the nature of the property; (p) the lessee must not, without the lessor's consent, erect on the property any permanent structure except for agricultural purposes; (q) on the determination of the lease, the lessee is bound to put the lessor into possession of the property."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER V", "OF LEASES OF IMMOVABLE PROPERTY", "109", "Rights of lessor's transferee.", "If the lessor transfers the property leased, or any part thereof, or any part of his interest in the property, the transferee, in the absence of a contract to the contrary, shall possess all the rights, and, if the lessee so elects, be subject to all the liabilities of the lessor as to the property or part transferred so long as he is the owner of it; but the lessor shall not, by reason only of such transfer cease to be subject to any of the liabilities imposed upon him by the lease, unless the lessee elects to treat the transferee as the person liable to him: Provided that the transferee is not entitled to arrears of rent due before the transfer, and that, if the lessee, not having reason to believe that such transfer has been made, pays rent to the lessor, the lessee shall not be liable to pay such rent over again to the transferee. The lessor, the transferee and the lessee may determine any question as to the apportionment of the rent by agreement among themselves or by a suit for apportionment."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER V", "OF LEASES OF IMMOVABLE PROPERTY", "110", "Exclusion of day on which term commences. Duration of lease for a year. Option to determine lease.", "Where the time so limited is a year or a number of years, in the absence of an express agreement to the contrary, the lease shall last during the whole anniversary of the day from which such time commences. Where the time so limited is expressed to be terminable before its expiration, and the lease omits to mention at whose option it is so terminable, the lessee, and not the lessor, shall have such option."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER V", "OF LEASES OF IMMOVABLE PROPERTY", "111", "Determination of lease.", "A lease of immovable property determines— (a) by efflux of the time limited thereby; (b) where such time is limited conditionally on the happening of some event—by the happening of such event; (c) where the interest of the lessor in the property terminates on, or his power to dispose of the same extends only to, the happening of any event—by the happening of such event; (d) in case the interests of the lessee and the lessor in the whole of the property become vested at the same time in one person in the same right; (e) by express surrender; that is to say, in case the lessee yields up his interest under the lease to the lessor, by mutual agreement between them; (f) by implied surrender; (g) by forfeiture; that is to say, (1) in case the lessee breaks an express condition which provides that, on breach thereof, the lessor may re-enter; or (2) in case the lessee renounces his character as such by setting up a title in a third person or by claiming title in himself; or (3) the lessee is adjudicated an insolvent and the lease provides that the lessor may re-enter on the happening of such event; and in any of these cases the lessor or his transferee gives notice in writing to the lessee of his intention to determine the lease; (h) on the expiration of a notice to determine the lease, or to quit, or of intention to quit, the property leased, duly given by one party to the other."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER V", "OF LEASES OF IMMOVABLE PROPERTY", "112", "Waiver of forfeiture.", "A forfeiture under section 111, clause (g) is waived by acceptance of rent which has become due since the forfeiture, or by distress for such rent, or by any other act showing an intention to treat the lease as subsisting: Provided that the lessor is aware that a forfeiture has been incurred: Provided also that, where rent is accepted after the institution of a suit to eject the lessee on the ground of forfeiture, such acceptance is not a waiver."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER V", "OF LEASES OF IMMOVABLE PROPERTY", "113", "Waiver of notice to quit.", "A notice given under section 111, clause (h), is waived, with the express or implied consent of the person to whom it is given, by any act on the part of the person giving it showing an intention to treat the lease as subsisting."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER V", "OF LEASES OF IMMOVABLE PROPERTY", "114", "Relief against forfeiture for non-payment of rent.", "Where a lease of immovable property has determined by forfeiture for non-payment of rent, and the lessor sues to eject the lessee, if, at the hearing of the suit, the lessee pays or tenders to the lessor the rent in arrear, together with interest thereon and his full costs of the suit, or gives such security as the Court thinks sufficient for making such payment within fifteen days, the Court may, in lieu of making a decree for ejectment, pass an order relieving the lessee against the forfeiture; and thereupon the lessee shall hold the property leased as if the forfeiture had not occurred."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER V", "OF LEASES OF IMMOVABLE PROPERTY", "114A", "Relief against forfeiture in certain other cases.", "Where a lease of immovable property has determined by forfeiture for a breach of an express condition which provides that on breach thereof the lessor may re-enter, no suit for ejectment shall lie unless and until the lessor has served on the lessee a notice in writing— (a) specifying the particular breach complained of; and (b) if the breach is capable of remedy, requiring the lessee to remedy the breach, and the lessee fails, within a reasonable time from the date of the service of the notice, to remedy the breach, if it is capable of remedy. Nothing in this section shall apply to an express condition against the assigning, under-letting, parting with the possession, or disposing, of the property leased, or to an express condition relating to forfeiture in case of non-payment of rent."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER V", "OF LEASES OF IMMOVABLE PROPERTY", "115", "Effect of surrender and forfeiture on under-leases.", "The surrender, express or implied, of a lease of immovable property does not prejudice an under-lease of the property or any part thereof previously granted by the lessee, on terms and conditions substantially the same (except as regards the amount of rent) as those of the original lease; but, unless the surrender is made for the purpose of obtaining a new lease, the rent payable by, and the covenants binding on, the under-lessee shall be respectively payable to and enforceable by the lessor. The forfeiture of such a lease annuls all such under-leases, except where such forfeiture has been procured by the lessor in fraud of the under-lessee."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER V", "OF LEASES OF IMMOVABLE PROPERTY", "116", "Effect of holding over.", "If a lessee or under-lessee of property remains in possession thereof after the determination of the lease granted to the lessee, and the lessor or his legal representative accepts rent from the lessee or under-lessee, or assents to his continuing in possession, the lease is, in the absence of an agreement to the contrary, renewed from year to year, or from month to month, according to the purpose for which the property is leased, as specified in section 106."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER V", "OF LEASES OF IMMOVABLE PROPERTY", "117", "Exemption of leases for agricultural purposes.", "None of the provisions of this Chapter apply to leases for agricultural purposes, except in so far as the State Government may by notification published in the Official Gazette declare all or any of such provisions to be so applicable, together with, or subject to, those of the local law, if any, for the time being in force. Such notification shall not take effect until the expiry of six months from the date of its publication."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER VI", "OF EXCHANGES", "118", "Exchange defined.", "When two persons mutually transfer the ownership of one thing for the ownership of another, neither thing or both things being money only, the transaction is called an \"exchange\". A transfer of property in completion of an exchange can be made only in manner provided for the transfer of such property by sale."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER VI", "OF EXCHANGES", "119", "Right of party deprived of thing received in exchange.", "If any party to an exchange or any person claiming through or under such party is by reason of any defect in the title of the other party deprived of the thing or any part of the thing received by him in exchange, then, unless a contrary intention appears from the terms of the exchange, such other party is bound to return the thing which he received in exchange, if still in his possession or power, and if not, to pay to the party deprived the fair value of the thing at the time of the exchange."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER VI", "OF EXCHANGES", "120", "Rights and liabilities of parties.", "Save as otherwise provided by this Chapter, each party has the rights and is subject to the liabilities of a seller as to that which he gives, and has the rights and is subject to the liabilities of a buyer as to that which he takes."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER VI", "OF EXCHANGES", "121", "Exchange of money.", "On an exchange of money, each party thereby warrants the genuineness of the money given by him."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER VII", "OF GIFTS", "122", "Gift defined.", "\"Gift\" is the transfer of certain existing movable or immovable property made voluntarily and without consideration, by one person, called the donor, to another, called the donee, and accepted by or on behalf of the donee. Acceptance must be made during the lifetime of the donor and while he is still capable of giving. If the donee dies before acceptance, the gift is void."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER VII", "OF GIFTS", "123", "Transfer how effected.", "For the purpose of making a gift of immovable property, the transfer must be effected by a registered instrument signed by or on behalf of the donor, and attested by at least two witnesses. For the purpose of making a gift of movable property, the transfer may be effected either by a registered instrument signed as aforesaid or by delivery. Such delivery may be made in the same way as goods sold may be delivered."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER VII", "OF GIFTS", "124", "Gift of existing and future property.", "A gift comprising both existing and future property is void as to the latter."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER VII", "OF GIFTS", "125", "Gift to several of whom one does not accept.", "A gift of a thing to two or more donees, of whom one does not accept it, is void as to the interest of the person who does not accept it."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER VII", "OF GIFTS", "126", "When gift may be suspended or revoked.", "The donor and donee may agree that on the happening of any specified event which does not depend on the will of the donor a gift shall be suspended or revoked; but a gift which the parties agree shall be revocable wholly or in part, at the mere will of the donor, is void wholly or in part, as the case may be. A gift may also be revoked in any of the cases (save want or failure of consideration) in which, if it were a contract, it might be rescinded. Save as aforesaid, a gift cannot be revoked. Nothing in this section shall be deemed to affect the rights of transferees for consideration without notice of a revocation."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER VII", "OF GIFTS", "127", "Onerous gifts.", "Where a gift is in the form of a single transfer to the same person of several things of which one is, and the others are not, burdened by an obligation, the donee can take nothing by the gift unless he accepts it fully. Where a gift is in the form of two or more separate and independent transfers to the same person of several things, the donee is at liberty to accept one of them and refuse the others, although the former may be beneficial and the latter onerous. Onerous gift to disqualified person.—A donee not competent to contract and accepting property burdened by an obligation is not bound by his acceptance. But if, after becoming competent to contract and being aware of the obligation, he retains the property given, he becomes so bound."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER VII", "OF GIFTS", "128", "Universal donee.", "Subject to the provisions of section 127, where a gift consists of the donor's whole property, the donee is personally liable for all the debts due by and liabilities of the donor at the time of the gift to the extent of the property comprised therein."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER VII", "OF GIFTS", "129", "Saving of donations mortis causa and Muhammadan Law.", "Nothing in this Chapter relates to gifts of movable property made in contemplation of death, or shall be deemed to affect any rule of Muhammadan law."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER VIII", "OF TRANSFERS OF ACTIONABLE CLAIMS", "130", "Transfer of actionable claim.", "(1) The transfer of an actionable claim whether with or without consideration shall be effected only by the execution of an instrument in writing signed by the transferor or his duly authorised agent, shall be complete and effectual upon the execution of such instrument, and thereupon all the rights and remedies of the transferor, whether by way of damages or otherwise, shall vest in the transferee, whether such notice of the transfer as is hereinafter provided be given or not: Provided that every dealing with the debtor or other person from or against whom the transferor would, but for this section, have been entitled to recover or enforce such actionable claim, shall, before notice of the transfer is given to such person, be valid as against such transfer. (2) The transferee of an actionable claim may, without prejudice to his rights against the transferor, sue or institute proceedings for the same in his own name without obtaining the transferor's consent to such suit or proceeding and without making him a party thereto. Exception.—Nothing in this section applies to the transfer of a marine or fire policy of insurance or affects the provisions of section 38 of the Insurance Act, 1938."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER VIII", "OF TRANSFERS OF ACTIONABLE CLAIMS", "130A", "Transfer of policy of marine insurance.", "[Repealed by the Marine Insurance Act, 1963 (11 of 1963), Section 92.]"],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER VIII", "OF TRANSFERS OF ACTIONABLE CLAIMS", "131", "Notice to be in writing, signed.", "Every notice of transfer of an actionable claim shall be in writing, signed by the transferor or his agent duly authorised in this behalf, or, in case the transferor refuses to sign, by the transferee or his agent, and shall state the name and address of the transferee."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER VIII", "OF TRANSFERS OF ACTIONABLE CLAIMS", "132", "Liability of transferee of actionable claim.", "The transferee of an actionable claim shall take it subject to all the liabilities and equities and to which the transferor was subject in respect thereof at the date of the transfer."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER VIII", "OF TRANSFERS OF ACTIONABLE CLAIMS", "133", "Warranty of solvency of debtor.", "Where the transferor of a debt warrants solvency of the debtor, the warranty applies only to his solvency at the time of the transfer, and is broken if the debt is not recovered owing to the insolvency of the debtor at the time of the transfer."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER VIII", "OF TRANSFERS OF ACTIONABLE CLAIMS", "134", "Mortgagee’s and lessee’s rights and obligations not affected by transfer.", "The transfer of an actionable claim shall not prejudice or affect any right of the transferor to recover or enforce such claim by any means which would have been available to him if the transfer had not been made, nor shall it affect the rights or obligations of any mortgagee or lessee of immovable property to which the transfer relates."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER VIII", "OF TRANSFERS OF ACTIONABLE CLAIMS", "135", "Assignment of rights under policy of insurance against fire.", "Every assignee, by endorsement or other writing, of a policy of insurance against fire, in whom the property in the subject insured shall be absolutely vested at the date of the assignment, shall have transferred and vested in him all rights of suit as if the contract contained in the policy had been made with himself."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER VIII", "OF TRANSFERS OF ACTIONABLE CLAIMS", "136", "Incapacity of officers connected with Courts of Justice.", "No judge, legal practitioner or officer connected with any Court of Justice shall buy or traffic in, or stipulate for, or agree to receive any share or interest in any actionable claim, and no Court of Justice shall enforce at his instance, or at the instance of any person claiming by or through him, any actionable claim so dealt with by him."],
  ["TRANSFER OF PROPERTY ACT, 1882", "CHAPTER VIII", "OF TRANSFERS OF ACTIONABLE CLAIMS", "137", "Saving of negotiable instruments, etc.", "Nothing in the foregoing sections of this Chapter applies to stocks, shares or debentures, or to instruments which are for the time being, by law or custom, negotiable, or to any mercantile document of title to goods."],
  ["TRANSFER OF PROPERTY ACT, 1882", "THE SCHEDULE", "Enactments repealed.", "[Repealed by the Repealing and Amending Act, 1914 (10 of 1914), Section 3 and Schedule II.]"]
];

function escapeSql(str) {
  if (typeof str !== 'string') return '';
  return str.replace(/'/g, "''");
}

let sql = 'INSERT INTO bare_act_sections (act_id, chapter_number, chapter_title, section_number, section_title, section_text, sequence_order) VALUES\\n';

